import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Harness 规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/spec/harness.md","filePath":"zh/spec/harness.md"}'),n={name:"zh/spec/harness.md"};function s(i,e,p,d,c,l){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="harness-规范" tabindex="-1">Harness 规范 <a class="header-anchor" href="#harness-规范" aria-label="Permalink to &quot;Harness 规范&quot;">​</a></h1><h2 id="当前执行层" tabindex="-1">当前执行层 <a class="header-anchor" href="#当前执行层" aria-label="Permalink to &quot;当前执行层&quot;">​</a></h2><p>Harness 位于 <code>apps/agentd</code>，运行在各 Work 的 Agent 容器中。它使用 Pi Agent SDK 进行模型调用、工具执行、资源加载、Sessions、Runs 和 SDK 历史管理。Core 仍负责生命周期与授权。</p><p><code>AGENTS.md</code>、选中的 Skills 和 Pi Packages 构成 Work 自有上下文。运行中的 Harness 加载已捕获的当前配置。编辑产生期望状态，显式 Apply 才会改变加载内容。源码编辑不会热更新当前 Run。</p><p>每个 Work 同时只有一个活跃 Run。模型执行发生在 Agent 中；浏览器和 CLI 不代理模型调用。Core 提供的模型凭据保持私有，不进入 <code>.work</code> 包。</p><h2 id="当前上下文和历史" tabindex="-1">当前上下文和历史 <a class="header-anchor" href="#当前上下文和历史" aria-label="Permalink to &quot;当前上下文和历史&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>职责</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Work 专属指令。</td></tr><tr><td>Skills</td><td>选中的指令资源。</td></tr><tr><td>Pi Packages</td><td>准备好的扩展、工具、提示词、主题及其他 SDK 资源。</td></tr><tr><td>Sessions 和 Runs</td><td>对话、执行记录和原始 SDK 历史。</td></tr><tr><td>当前 / 期望上下文</td><td>已加载配置与待生效修改。</td></tr></tbody></table><p>Core 在激活前验证包兼容性。当前可携带包保留已准备的产物和依赖；导入不会重新运行 npm、Git 或包代码来重建它们。</p><h2 id="实验性-piwork-brain" tabindex="-1">实验性：<code>piwork-brain</code> <a class="header-anchor" href="#实验性-piwork-brain" aria-label="Permalink to &quot;实验性：`piwork-brain`&quot;">​</a></h2><p>默认 brain 是普通 Pi 扩展包。Core 只初始化一次；后续启动不会重置管理员的修改。新 Work 默认选择它，除非配置明确不选包。</p><p>已实现流程有四个边界：</p><ol><li><strong>观察并操作：</strong> Harness 读取 Service 能力契约、观察状态、记录稳定的 Action 身份，并发送已声明输入和期望状态版本。</li><li><strong>验证：</strong> 成功描述或 Run 结束不足以证明完成。同步修改需要实际观察；异步任务保留原始 Action / Job 引用，供后续验证。</li><li><strong>保留经验：</strong> 候选规则只有在关联任务验证成功后，才成为有效经验版本。活跃 Run 保持已采用的版本；下一次执行可以采用新版本。</li><li><strong>准备并 Apply：</strong> 可编辑的 brain 源码可以被捕获和准备为候选包。用户显式 Apply 后，还需要相应行为检查。准备完成或加载成功本身，不证明修改有效。</li></ol><p>Work 就绪且没有活跃 Run 时，Service 事件可以请求有边界的自动执行。请求、取消、重试和恢复都有稳定身份及期限。重启不会重放结果不明的修改。</p><p>导出保留这些持久历史。导入的事件和请求仅作为历史，不能调度或重放来源实例上的副作用。</p><h2 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h2><p>Harness 越来越适合特定 Work 和用户，是产品方向。当前系统不保证无限制自主学习、不可见的自动升级，也不保证所有应用都有结构化能力接口。</p><p>权威来源：<a href="https://github.com/pphboy/piwork/blob/main/docs/piwork-brain.md" target="_blank" rel="noreferrer">brain 工作流程</a>、<a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">brain 规范</a>、<a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation 规范</a>和<a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/pi-package-activation/spec.md" target="_blank" rel="noreferrer">包激活规范</a>。</p>',17)])])}const k=r(n,[["render",s]]);export{b as __pageData,k as default};
